parameters.jsonBody:
={{ JSON.stringify({ query: "query Open($team: String!) {
  issues(first: 150, filter: { team: { key: { eq: $team } }, state: { type: { nin: ["canceled"] } } }) {
    nodes { id identifier title description url state { name } project { name } }
  }
}", variables: { team: $json.team_key } }) }}

parameters.jsCode:
// Trim the issue list so the agent sees only what it needs to judge duplicates.
const nodes = $input.first().json.data?.issues?.nodes ?? [];
const issues = nodes.map(i => ({
  id: i.id, identifier: i.identifier, title: i.title, url: i.url,
  state: i.state?.name, project: i.project?.name ?? null,
  description: (i.description ?? '').slice(0, 400),
}));
return [{ json: { feedback_text: $('Called by orchestrator').first().json.feedback_text,
                  reporter: $('Called by orchestrator').first().json.reporter, issues } }];

parameters.text:
=Bug report from {{ $json.reporter }}:
{{ $json.feedback_text }}

Current Linear issues (JSON):
{{ JSON.stringify($json.issues) }}

